    {
      "item": "Encryption requirements",
      "question": "Do you require PGP or platform-managed encryption? If PGP, please provide the public key."
    },
    {
      "item": "Customer interactions scope",
      "question": "Which systems/objects should be included? (e.g., support tickets/cases, case comments, email metadata, chat transcripts, call logs, CSAT/surveys, escalations)."
