  "proposed_scope_outline_for_confirmation": {
    "billing_objects": [
      "subscriptions and plan changes (current + history)",
      "invoices and invoice line items",
      "payments/charges and refunds",
      "credit notes/adjustments",
      "discounts/coupons/taxes",
      "payment methods (masked/tokenized), brand, last4, expiry (if applicable)",
      "balance transactions/account credits"
    ],
    "interaction_objects": [
      "support tickets/cases",
      "case comments/internal notes",
      "email thread metadata",
      "chat/call log metadata",
      "CSAT/surveys and escalations"
    ],
    "fields": "All standard fields plus system IDs and timestamps; content bodies only if explicitly approved."
  },
