    "scope_signoff": "Within 2 business hours after you provide the remaining details",
    "governance_approval": "Same business day expedite where possible",
    "extraction_and_QA": "Approximately 1 business day after approval (volume-dependent)",
    "delivery": "Target 24–36 hours from approval; we will update you with a firm ETA"
  },
  "draft_governed_request_summary_for_your_review": {
    "case_id": "case_901",
    "purpose": "Audit/compliance",
    "date_range": "Last 6 months (exact dates to be confirmed)",
    "datasets": [
      "Billing: subscriptions, invoices, invoice lines, payments, refunds, credits, discounts, taxes, payment methods (masked/tokenized)",
      "Customer interactions: tickets/cases, comments/notes, email/chat/call metadata, CSAT/surveys, escalations"
    ],
    "delivery": {
      "format": "CSV",
      "packaging": "One CSV per object, compressed",
      "destination": "Secure folder (details pending)",
      "encryption": "Pending preference (PGP or platform-managed)"
    },
    "retention": "30 days",
    "approvals": {
      "manager": "[Manager's Name]",
      "contact": "Pending email/ticket",
      "data_owner": "[Your Name]"
    }
  },
  "next_step_prompt": "Please provide the remaining items (deadline/timezone, secure folder details, encryption preference/public key, interaction systems to include, content vs. metadata preference, sensitive data handling, exact date range, identifiers, file packaging preferences, and manager contact/ticket). I will submit the urgent governed-export request immediately upon receipt and keep you updated on progress."
}

